"""Print compact score breakdowns from an atira eval dev log: score.py <log>"""
import json
import sys

for line in open(sys.argv[1]):
    line = line.strip()
    if not line.startswith("{") or '"score"' not in line:
        continue
    try:
        data = json.loads(line)
    except ValueError:
        continue
    answer = data.get("answer") or data
    score = answer.get("score") or {}
    print("quality", score.get("quality"), "at", answer.get("at"))
    b = score.get("breakdown", {})
    for k, v in b.items():
        if k != "positions":
            print(" ", k, v)
    for p in b.get("positions", []):
        bad = {k: (v.get("expected"), v.get("got")) for k, v in p.items()
               if isinstance(v, dict) and v.get("expected") != v.get("got")}
        print("  pos", p.get("position"), "points", p.get("points"), "wrong", bad)

