"""Bench the Q&A reader thinking on vs off on Q&A pages kept in traces: qa_bench.py <trace.jsonl> <reference> [runs]"""
import asyncio
import json
import sys
import time
from datetime import datetime, UTC

sys.path.insert(0, "/Users/jonasstenglein/OtherProjects/EHL_Finale/error404ai_ehl_finals/.claude/worktrees/agent-a8b7ef45f5802af58/agent")

import research_tender  # noqa: E402

path, reference = sys.argv[1], sys.argv[2]
runs = int(sys.argv[3]) if len(sys.argv) > 3 else 2
kept, views = [], {}
for line in open(path):
    e = json.loads(line)
    if e["kind"] == "nav_done" and (e["worker"].endswith(":tender") or e["worker"].endswith(":qa")):
        kept += e["kept"].get("qa", [])
    if e["kind"] == "view" and e.get("http"):
        views[e["url"]] = f"URL: {e['url']}\nTitle: \n\n{e['text']}"
pages = []
for k in kept:
    for url, v in views.items():
        if url.endswith(k.replace("&amp;", "&")) and v not in pages:
            pages.append(v)
print(len(pages), "pages", sum(len(p) for p in pages), "chars")


def summary(qa):
    f = research_tender.resolve_tender([], qa, datetime(2100, 1, 1, tzinfo=UTC))
    out = {name: sorted((r.answer_number, r.model_dump_json(exclude={"answer_number", "date"}))
                        for r in getattr(qa, name)) for name in research_tender.QaRecords.model_fields
           if name != "number_format"}
    return json.dumps(out, sort_keys=True)


async def main():
    results = {}
    for thinking in (True, False):
        research_tender.reader_settings = (lambda t=thinking: research_tender.llm.settings(
            thinking=t, timeout=180.0))
        for i in range(runs):
            t = time.monotonic()
            qa = await research_tender.read_qa(pages, reference)
            s = summary(qa)
            results.setdefault(thinking, []).append(s)
            print("thinking" if thinking else "fast", i, round(time.monotonic() - t, 1), "s", flush=True)
    base = results[True][0]
    for thinking, outs in results.items():
        print("thinking" if thinking else "fast", ["same" if o == base else "DIFF" for o in outs])
    if any(o != base for outs in results.values() for o in outs):
        for thinking, outs in results.items():
            for o in outs:
                if o != base:
                    a, b = json.loads(base), json.loads(o)
                    for k in a:
                        if a[k] != b[k]:
                            print("thinking" if thinking else "fast", k, "\n  base", a[k], "\n  this", b[k])


asyncio.run(main())

