"""HTTP research helpers: the navigator's view and checks, list continuation, deferred ERP hits, Q&A elsewhere."""
import asyncio
import sys
import unittest
from decimal import Decimal as D
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from evidence import Candidate, EffectiveRequirement, RequirementResearch  # noqa: E402
from http_nav import Keep, Navigator, Request, Step  # noqa: E402
from http_read import html_view  # noqa: E402
from http_site import Page  # noqa: E402
import research_http  # noqa: E402
from research_http import DeferredHits, _continues  # noqa: E402


class FakeTrace:
    def __init__(self):
        self.events = []

    def event(self, worker, kind, quiet=False, **data):
        self.events.append((worker, kind, data))


class FakeSite:
    base = "http://portal.example/"

    def __init__(self):
        self.trace = FakeTrace()
        self.name = "portal"

    def url(self, target, base=None):
        from urllib.parse import urljoin
        return urljoin(base or self.base, target.strip())

    def on_site(self, url):
        return url.startswith(self.base)


def page(url: str, html: str) -> Page:
    view = html_view(html)
    return Page(url, view.title, view.text, view.forms, asked=url)


HOME = ("<html><body><form method=post action=/logout><button>Sign out</button></form>"
        "<a href=/docs>Documents</a> <a href=/abmelden>Abmelden</a>"
        "<form action=/search><input name=q><button>Search</button></form></body></html>")


class NavigatorView(unittest.TestCase):
    def setUp(self):
        self.nav = Navigator(FakeSite(), "goal", {"M-100": "the views of material M-100", "qa": "answers"})
        self.home = page("http://portal.example/", HOME)
        self.nav.show(self.home)

    def test_sign_out_controls_are_hidden(self):
        shown = self.nav.rendered[0]
        self.assertNotIn("logout", shown)
        self.assertNotIn("Abmelden", shown)
        self.assertIn("/docs", shown)
        self.assertIn("[form 2 GET -> /search]", shown)  # the other form keeps its number

    def test_category_written_with_its_description_is_mapped(self):
        step = Step(keep=[Keep(category="M-100: the views of material M-100", pages=["/"])],
                    requests=[Request(target="/docs", keep_as="QA")])
        self.assertEqual(self.nav.check(step), [])
        self.assertEqual(step.keep[0].category, "M-100")
        self.assertEqual(step.requests[0].keep_as, "qa")

    def test_a_page_already_shown_may_be_requested_again(self):
        self.assertEqual(self.nav.check(Step(requests=[Request(target="/", all_pages=True)])), [])

    def test_made_up_addresses_are_refused(self):
        problems = self.nav.check(Step(requests=[Request(target="/docs?page=2")]))
        self.assertTrue(problems and "appears on no page" in problems[0])


class Continues(unittest.TestCase):
    def test_next_link_or_unread_frame_continues(self):
        self.assertTrue(_continues(page("http://portal.example/r", '<a href="/r?p=2">Weiter</a>')))
        self.assertTrue(_continues(Page("http://portal.example/r", "", "[frame /x] (separate)")))

    def test_whole_page_does_not(self):
        self.assertFalse(_continues(page("http://portal.example/r", '<a href="/r?p=0">Zurück</a> <p>R-1 | 50</p>')))


def requirement(**kw) -> EffectiveRequirement:
    values = dict(requirement_id="R-1", catalog_group="KG-1", bore=D("50"), stroke=D("200"), pressure=D("160"),
                  mounting="Flansch", certification="keine")
    values.update(kw)
    return EffectiveRequirement(**values)


class FakeOrchestrator:
    def __init__(self):
        self.trace = FakeTrace()
        self.erp = None
        self.asked = []

    async def _details(self, site_id, numbers, links):
        self.asked.append(list(numbers))
        return {n: f"record {n}" for n in numbers}


class Deferred(unittest.TestCase):
    def setUp(self):
        self.orch = FakeOrchestrator()
        self.hits = DeferredHits(self.orch, "erp", {"M-2": "/m/M-2", "M-3": "/m/M-3"})
        research = RequirementResearch(requirement_id="R-1", candidates=[
            Candidate(material_number="M-2", bore=D("50"), stroke=D("250"), pressure=D("160")),
            Candidate(material_number="M-3", bore=D("63"), stroke=D("200"), pressure=D("160"))])
