class HybridQaRead(unittest.TestCase):
    """read_qa_page_hybrid: the thinking reading counts when it comes in time; the fast one fills its gaps."""

    def run_hybrid(self, slow_seconds: float):
        import research_tender as rt
        from datetime import datetime, UTC
        when = datetime(2026, 1, 5, tzinfo=UTC)

        async def fake(page, reference, thinking=True):
            if thinking:
                await asyncio.sleep(slow_seconds)
                return rt.QaPage(answers=["1"], withdrawals=[rt.QaWithdrawal(answer_number="1", date=when,
                                                                             withdrawn_number="0")])
            return rt.QaPage(answers=["1", "2"], withdrawals=[rt.QaWithdrawal(answer_number="1", date=when,
                                                                              withdrawn_number="9")],
                             packaging_tariffs=[rt.QaKey(answer_number="2", date=when, position="10", key="VP-11")])

        saved = rt.read_qa_page, rt.QA_THINKING_GRACE
        rt.read_qa_page, rt.QA_THINKING_GRACE = fake, 0.2
        try:
            return asyncio.run(rt.read_qa_page_hybrid("page", "REF-1"))
        finally:
            rt.read_qa_page, rt.QA_THINKING_GRACE = saved

    def test_thinking_in_time_wins_and_fast_adds_answers(self):
        out = self.run_hybrid(0.01)
        self.assertEqual([w.withdrawn_number for w in out.withdrawals], ["0"])  # answer 1 as the thinking read
        self.assertEqual([k.key for k in out.packaging_tariffs], ["VP-11"])  # answer 2 only the fast one had
        self.assertEqual(out.answers, ["1", "2"])

    def test_late_thinking_leaves_the_fast_reading(self):
        out = self.run_hybrid(2.0)
        self.assertEqual([w.withdrawn_number for w in out.withdrawals], ["9"])


